export interface RateTable {
  base: string;
  rates: Record<string, number>;
  fetchedAt: number;
}

export interface RateProvider {
  fetch(base: string): Promise<RateTable>;
}

export interface RateCache {
  get(base: string): Promise<RateTable | undefined>;
  set(base: string, table: RateTable): Promise<void>;
}

export interface Logger {
  info(message: string, fields?: Record<string, unknown>): void;
  warn(message: string, fields?: Record<string, unknown>): void;
}

export interface RateServiceOptions {
  /** How long a fetched table counts as fresh, in milliseconds. */
  maxAgeMs: number;
  now?: () => number;
}

export class UnknownCurrencyError extends Error {
  constructor(public readonly currency: string, public readonly base: string) {
    super(`no ${currency} rate for base ${base}`);
    this.name = 'UnknownCurrencyError';
  }
}

/**
 * Serves exchange rates from the cache and refreshes them from the provider
 * once they are older than maxAgeMs.
 */
export class RateService {
  private readonly maxAgeMs: number;
  private readonly now: () => number;
  private staleServed = 0;

  constructor(
    private readonly provider: RateProvider,
    private readonly cache: RateCache,
    private readonly logger: Logger,
    options: RateServiceOptions,
  ) {
    if (!Number.isFinite(options.maxAgeMs) || options.maxAgeMs <= 0) {
      throw new RangeError(`maxAgeMs must be a positive number, got ${options.maxAgeMs}`);
    }
    this.maxAgeMs = options.maxAgeMs;
    this.now = options.now ?? Date.now;
  }

  /** Number of times an expired table was served because the provider failed. */
  get staleServedCount(): number {
    return this.staleServed;
  }

  /**
   * Returns the rate table for base. A fresh cached table is served as is.
   * An expired one is refreshed; when the provider fails and an expired
   * table exists, that table is served rather than failing the request.
   */
  async getRates(base: string): Promise<RateTable> {
    const cached = await this.cache.get(base);
    if (cached && !this.isExpired(cached)) {
      return cached;
    }
    try {
      return this.refresh(base);
    } catch (err) {
      if (!cached) {
        throw err;
      }
      this.staleServed += 1;
      this.logger.warn('rate provider failed, serving expired rates', {
        base,
        fetchedAt: cached.fetchedAt,
        error: err instanceof Error ? err.message : String(err),
      });
      return cached;
    }
  }

  /** Fetches the table for base from the provider and caches it. */
  async refresh(base: string): Promise<RateTable> {
    const fresh = await this.provider.fetch(base);
    await this.cache.set(base, fresh);
    this.logger.info('rates refreshed', { base, fetchedAt: fresh.fetchedAt });
    return fresh;
  }

  /** Converts amount from the base currency into the target currency. */
  async convert(amount: number, base: string, target: string): Promise<number> {
    if (base === target) {
      return amount;
    }
    const table = await this.getRates(base);
    const rate = table.rates[target];
    if (rate === undefined) {
      throw new UnknownCurrencyError(target, base);
    }
    return amount * rate;
  }

  private isExpired(table: RateTable): boolean {
    return this.now() - table.fetchedAt > this.maxAgeMs;
  }
}
